//
// The setup questionnaire speaks the app's five languages (#1366).
//
// `web/setup.html` is the first thing a new owner reads, and until #1366
// it spoke only French: `<html lang="fr">`, a French-only copy of the
// feature catalogue, French validation messages and a French confirm()
// dialog. An owner in Munich met a page the app itself would never show.
//
// Now every word on the page comes from `web/setup_l10n.js`, generated by
// `tool/build_setup_l10n.dart` from two sources: the app's ARB catalogue
// for anything the app already names (features, permissions, validation
// domains, countries), and `web/setup_l10n/setup_<locale>.json` for the
// page's own prose. These tests keep it that way:
//
//  * the generated file is what the generator produces today (a committed
//    generated file with no drift gate drifts silently);
//  * every locale carries exactly the keys English does, none blank, with
//    the same placeholders;
//  * every WorkspaceFeature reads, in every locale, exactly what the app's
//    Features screen reads — the page keeps no sixth copy of the catalogue;
//  * every key the page asks for exists, and none is orphaned;
//  * no French literal is left in the page itself (a heuristic lint, with a
//    test proving it fires).
//
// The behaviour half — each locale renders, sets <html lang> and the title,
// shows no French outside French, and exports byte-identical XML — runs in
// tool/setup/step_harness.mjs, driven by setup_runs_test.dart.
import 'dart:convert';
import 'dart:io';

import 'package:deskilo/core/country/country_catalog.dart';
import 'package:deskilo/features/events/domain/workspace_event.dart';
import 'package:deskilo/features/workspace/domain/workspace_feature.dart';
import 'package:deskilo/features/workspace/domain/workspace_permission.dart';
import 'package:deskilo/features/workspace/domain/workspace_process.dart';
import 'package:deskilo/features/workspace/presentation/feature_copy.dart';
import 'package:deskilo/features/workspace/presentation/feature_names.dart';
import 'package:deskilo/features/workspace/presentation/process_names.dart';
import 'package:deskilo/l10n/app_localizations.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

import '../../tool/build_setup_l10n.dart';
import '../../tool/setup/page_sources.dart';

const _html = 'web/setup.html';
const _prefix = 'window.SETUP_L10N=';

/// The generated resource, decoded.
Map<String, dynamic> _decode(String js) {
  final start = js.indexOf(_prefix);
  final end = js.lastIndexOf(';');
  return jsonDecode(js.substring(start + _prefix.length, end))
      as Map<String, dynamic>;
}

Set<String> _placeholders(String value) => {
  for (final m in RegExp(r'\{(\w+)\}').allMatches(value)) m.group(1)!,
};

/// Characters French prose carries and the page's code never needs.
final _frenchLetters = RegExp('[àâçéèêëîïôûùœÀÂÇÉÈÊÎÔÛÙŒ«»’]');

/// Accent-free words the page used to show — the ones an accent check
/// alone would let back in.
final _frenchWords = RegExp(
  r'\b(Suivant|Terminer|Exporter|Charger|Effacer|Ajouter|Supprimer|'
  r'Corriger|Masqué|requis|Oui|Non|Aucun|Aucune|Fichier|Jours|Nom|Prix|'
  r'Ville|Rue|Pays|Devise|Langue|Membres?|Abonnement|Forfaits?|Palier|'
  r'Relances?|Enregistr\w*|Assistant de configuration|mode expert|'
  r'toutes les)\b',
);

/// Markup text a reader would see: anything left once tags are stripped.
final _visibleWord = RegExp(r'[A-Za-zÀ-ÿ]{3,}');

/// The line numbers (1-based, with the line) of French natural language in
/// [html] outside the l10n resource.
///
/// Heuristic, deliberately. In `<script>`, a code line (not a `//` comment)
/// is flagged for a French letter or a former French literal. In markup,
/// every line is checked the same way — attribute values included, since
/// an `onclick="confirm('…')"` is prose — and additionally any visible
/// text node is flagged, because the page's chrome is filled from
/// `data-t` keys and its markup should carry no words at all. `<style>`
/// is skipped, and so is the one block between `l10n-exempt-begin` and
/// `l10n-exempt-end` (language names, statutory VAT labels, XML fallbacks).
List<String> frenchLiterals(String html) {
  final findings = <String>[];
  var inScript = false;
  var inStyle = false;
  var exempt = false;
  final lines = html.split('\n');
  for (var i = 0; i < lines.length; i++) {
    final line = lines[i];
    final trimmed = line.trim();
    if (trimmed.contains('l10n-exempt-begin')) {
      exempt = true;
      continue;
    }
    if (trimmed.contains('l10n-exempt-end')) {
      exempt = false;
      continue;
    }
    if (exempt) continue;
    if (line.contains('<style')) inStyle = true;
    if (inStyle) {
      if (line.contains('</style>')) inStyle = false;
      continue;
    }
    // A `<script>` opening line may carry markup before it; a `<script
    // src=…></script>` pair opens nothing.
    final opensScript = RegExp(r'<script>').hasMatch(line);
    if (inScript || opensScript) {
      if (line.contains('</script>')) inScript = false;
      if (opensScript && !line.contains('</script>')) inScript = true;
      if (trimmed.startsWith('//')) continue;
      if (_frenchLetters.hasMatch(line) || _frenchWords.hasMatch(line)) {
        findings.add('${i + 1}: $trimmed');
      }
      continue;
    }
    final text = line.replaceAll(RegExp(r'<[^>]*>'), ' ');
    final words = _visibleWord
        .allMatches(text)
        .map((m) => m.group(0)!)
        .where((w) => w != 'DesKilo' && w != 'DOCTYPE' && w != 'html');
    if (_frenchLetters.hasMatch(line) ||
        _frenchWords.hasMatch(line) ||
        words.isNotEmpty) {
      findings.add('${i + 1}: $trimmed');
    }
  }
  return findings;
}

void main() {
  late String html;
  // #2926 — the page with the scripts it is split into.
  late String page;
  late Map<String, dynamic> resource;

  setUpAll(() {
    html = File(_html).readAsStringSync();
    page = setupPageSource();
    resource = _decode(File(setupL10nOutput).readAsStringSync());
  });

  test('web/setup_l10n.js is what build_setup_l10n produces today', () {
    expect(
      File(setupL10nOutput).readAsStringSync(),
      buildSetupL10n(),
      reason:
          'the setup questionnaire\'s strings drifted from their sources '
          '(ARB or web/setup_l10n/*.json) — run '
          '`dart run tool/build_setup_l10n.dart` and commit the result',
    );
  });

  // #1330 — the page groups its switches by the app's process registry.
  // The structure is generated (setup_catalogue.js), the words ride in the
  // l10n resource; neither may drift from workspace_process.dart.
  group('process catalogue', () {
    test('web/setup_catalogue.js is what build_setup_l10n produces today', () {
      expect(
        File(setupCatalogueOutput).readAsStringSync(),
        buildSetupCatalogue(),
        reason:
            'the setup questionnaire\'s process catalogue drifted from '
            'workspaceProcesses — run `dart run tool/build_setup_l10n.dart` '
            'and commit the result',
      );
    });

    test('the catalogue is the registry: every process, every subprocess, '
        'every capability, in order', () {
      const prefix = 'window.SETUP_PROCESSES=';
      final js = File(setupCatalogueOutput).readAsStringSync();
      final start = js.indexOf(prefix);
      // #2868 — the levels and obligations follow in the same file.
      final decoded =
          jsonDecode(
                js.substring(
                  start + prefix.length,
                  js.indexOf('\n];\n', start) + 2,
                ),
              )
              as List<dynamic>;
      final want = [
        for (final p in workspaceProcesses)
          {
            'key': p.key,
            'subprocesses': [
              for (final sp in p.subprocesses)
                {
                  'key': sp.key,
                  'features': [for (final f in sp.capabilities) f.name],
                },
            ],
          },
      ];
      expect(decoded, want);
      // Every switch the page offers has exactly one home, or is a
      // reserved flag the page lists under "Technical".
      final placed = <String>[
        for (final p in workspaceProcesses)
          for (final sp in p.subprocesses)
            for (final f in sp.capabilities) f.name,
      ];
      expect(placed.toSet().length, placed.length, reason: 'a feature twice');
      final internal = internalCapabilities.keys.map((f) => f.name).toSet();
      expect(
        WorkspaceFeature.values.map((f) => f.name).toSet(),
        placed.toSet().union(internal),
      );
    });

    for (final locale in setupLocales) {
      test('every process and subprocess reads in $locale exactly as the app '
          'names it', () {
        final l10n = lookupAppLocalizations(Locale(locale));
        final strings = resource[locale] as Map;
        final processes = strings['process'] as Map<String, dynamic>;
        final subprocesses = strings['subprocess'] as Map<String, dynamic>;
        final wrong = <String>[];
        for (final p in workspaceProcesses) {
          final copy = processCopy(l10n, p.key);
          final row = processes[p.key] as List<dynamic>?;
          if (row == null ||
              row[0] != copy.title ||
              row[1] != copy.description) {
            wrong.add(p.key);
          }
          for (final sp in p.subprocesses) {
            final sub = processCopy(l10n, sp.key);
            final subRow = subprocesses[sp.key] as List<dynamic>?;
            if (subRow == null ||
                subRow[0] != sub.title ||
                subRow[1] != sub.description) {
              wrong.add(sp.key);
            }
          }
        }
        expect(wrong, isEmpty);
      });
    }
  });

  group('page strings', () {
    Map<String, dynamic> strings(String locale) =>
        jsonDecode(File(setupStringsPath(locale)).readAsStringSync())
            as Map<String, dynamic>;

    for (final locale in setupLocales) {
      test('$locale has exactly the English keys, none blank, same '
          'placeholders', () {
        final en = strings('en');
        final own = strings(locale);
        expect(
          own.keys.toSet().difference(en.keys.toSet()),
          isEmpty,
          reason: 'keys $locale has and en does not',
        );
        expect(
          en.keys.toSet().difference(own.keys.toSet()),
          isEmpty,
          reason: 'keys $locale is missing',
        );
        final blank = [
          for (final e in own.entries)
            if (e.value is! String || (e.value as String).trim().isEmpty) e.key,
        ];
        expect(blank, isEmpty, reason: 'blank values in $locale');
        final drifted = [
          for (final key in en.keys)
            if (!_setEquals(
              _placeholders(en[key] as String),
              _placeholders(own[key] as String),
            ))
              key,
        ];
        expect(
          drifted,
          isEmpty,
          reason:
              'placeholders differ from en in $locale — the page '
              'fills them by name',
        );
      });
    }

    test('every key the page asks for exists, and no key is orphaned', () {
      final en = strings('en');
      // The WebMCP tools (#2501) speak through the same resource.
      final tools = File('web/setup_webmcp.js').readAsStringSync();
      final asked = {
        for (final m in RegExp(r"\bT\('(\w+)'").allMatches('$page\n$tools'))
          m.group(1)!,
        for (final m in RegExp(r'data-th?="(\w+)"').allMatches(page))
          m.group(1)!,
      };
      expect(
        asked.difference(en.keys.toSet()),
        isEmpty,
        reason:
            'setup.html asks for keys web/setup_l10n/setup_en.json '
            'does not have — it would show the raw key',
      );
      final orphans = [
        for (final key in en.keys)
          if (!page.contains("'$key'") &&
              !page.contains('"$key"') &&
              !tools.contains("'$key'"))
            key,
      ];
      expect(
        orphans,
        isEmpty,
        reason:
            'keys nothing in setup.html reads any more — delete them '
            'from all five JSON files',
      );
    });
  });

  group('catalogue', () {
    for (final locale in setupLocales) {
      test('every WorkspaceFeature reads in $locale exactly as the app '
          'names and describes it', () {
        final l10n = lookupAppLocalizations(Locale(locale));
        final features =
            (resource[locale] as Map)['feature'] as Map<String, dynamic>;
        expect(
          features.keys.toSet(),
          WorkspaceFeature.values.map((f) => f.name).toSet(),
        );
        final wrong = <String>[];
        for (final f in WorkspaceFeature.values) {
          final row = features[f.name] as List<dynamic>;
          final name = featureName(l10n, f);
          final description = featureDescription(l10n, f);
          if (row[0] != name || row[1] != description) wrong.add(f.name);
          if (name.trim().isEmpty || description.trim().isEmpty) {
            wrong.add('${f.name} (blank)');
          }
        }
        expect(wrong, isEmpty);
      });
    }
  });

  // #2923 — the page keeps no copy of the app's registries: the switches,
  // their defaults and tree, the permissions and their default matrix, the
  // validation domains and the countries arrive in SETUP_REGISTRY. The file
  // is drift-gated above; this pins what it MEANS against the app's own
  // functions, so a generator that read the wrong source fails here.
  group('registry', () {
    late Map<String, dynamic> registry;
    setUpAll(() {
      const prefix = 'window.SETUP_REGISTRY=';
      final js = File(setupCatalogueOutput).readAsStringSync();
      final start = js.indexOf(prefix) + prefix.length;
      registry =
          jsonDecode(js.substring(start, js.indexOf('\n};\n', start) + 2))
              as Map<String, dynamic>;
    });

    test('every WorkspaceFeature, with the default a new workspace gets', () {
      final defaults = defaultFeatureFlagsForNewWorkspace();
      expect(registry['features'], [
        for (final f in WorkspaceFeature.values) [f.name, defaults[f.name]],
      ]);
    });

    test('requires and availableIn are featureManifest\'s', () {
      expect(registry['requires'], {
        for (final e in featureManifest.entries)
          if (e.value.requires != null) e.key.name: e.value.requires!.name,
      });
      expect(
        (registry['availableIn'] as Map).map(
          (k, v) => MapEntry(k, (v as List).toSet()),
        ),
        {
          for (final e in featureManifest.entries)
            if (e.value.availableIn != null)
              e.key.name: e.value.availableIn!.toSet(),
        },
      );
    });

    test('every permission in the roles screen order, and the default '
        'matrix the app starts a workspace from', () {
      final all = [for (final p in WorkspacePermission.values) p.wireName];
      expect(registry['permissions'], all);
      final everyday = everydayMatrix();
      final matrix = registry['defaultMatrix'] as Map<String, dynamic>;
      expect(matrix.keys, ['co_owner', 'admin', 'member']);
      expect(matrix['co_owner'], all);
      expect(matrix['admin'], everyday['admin']);
      expect(matrix['member'], everyday['member']);
    });

    test('every validation domain is an event type the server stores', () {
      final wire = {for (final t in EventType.values) t.dbName};
      final types = registry['domainEventTypes'] as Map<String, dynamic>;
      for (final d in (registry['domains'] as List).cast<String>()) {
        expect(wire, contains(types[d] ?? d), reason: d);
      }
      final features = {for (final f in WorkspaceFeature.values) f.name};
      for (final gate in (registry['domainGates'] as Map).values) {
        expect(features, contains(gate));
      }
    });

    test('the countries are the CountryCatalog', () {
      expect(registry['countries'], [
        for (final c in CountryCatalog.countries)
          [c.code, c.currencyCode, c.defaultTimezone, c.scheme.name],
      ]);
    });
  });

  group('the page', () {
    test('loads the resource before its own script and hardcodes no '
        'language', () {
      final resourceTag = html.indexOf('<script src="setup_l10n.js"></script>');
      final catalogueTag =
          html.indexOf('<script src="setup_catalogue.js"></script>');
      final inline = html.indexOf('<script>');
      expect(resourceTag, isNot(-1));
      expect(resourceTag, lessThan(inline));
      expect(catalogueTag, isNot(-1));
      expect(catalogueTag, lessThan(inline));
      expect(html, isNot(contains('lang="fr"')));
      expect(
        RegExp('<title>DesKilo</title>').hasMatch(html),
        isTrue,
        reason: 'the title is set from the chosen locale at load',
      );
    });

    test('carries no French literal outside the l10n resource', () {
      expect(
        frenchLiterals(page),
        isEmpty,
        reason:
            'user-facing text belongs in web/setup_l10n/setup_*.json '
            '(or the app ARB), read through T(key)',
      );
    });

    test('the exempt block stays small', () {
      final start = page.indexOf('l10n-exempt-begin');
      final end = page.indexOf('l10n-exempt-end');
      expect('l10n-exempt-begin'.allMatches(page), hasLength(1));
      expect(
        page.substring(start, end).split('\n').length,
        lessThanOrEqualTo(26),
        reason:
            'the exemption is for language names, statutory VAT '
            'labels and XML fallbacks — not a place to park prose',
      );
    });

    test('the French-literal lint fires on what it must catch', () {
      const page = '''
<!DOCTYPE html>
<html lang="en">
<body>
<p>Tout afficher sur une page</p>
<button onclick="if(confirm('Effacer toutes les réponses ?')){}"></button>
<span data-t="setupReset"></span>
<script src="setup_l10n.js"></script>
<script>
const a='Suivant';
// Un commentaire en français n'est pas affiché.
h('p',{},"Réglages de l'espace");
const b=T('setupNext');
// l10n-exempt-begin
const ENDONYMS={fr:'Français'};
// l10n-exempt-end
</script>
</body>
</html>''';
      final found = frenchLiterals(page).map((f) => f.split(':').first);
      expect(found, ['4', '5', '9', '11']);
    });
  });
}

bool _setEquals(Set<String> a, Set<String> b) =>
    a.length == b.length && a.containsAll(b);
